"/**
 * SketchTrace Storage Service
 * Handles IndexedDB & LocalStorage persistence for:
 * - User Profile & Auth
 * - Favorites
 * - Recently Opened Sketches
 * - Downloaded Offline Sketches
 * - Custom Uploads & AI Converted Sketches
 * - Theme Preferences
 */

const DB_NAME = 'SketchTraceDB';
const DB_VERSION = 1;

class StorageService {
  constructor() {
    this.db = null;
    this.initDB();
  }

  async initDB() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains('favorites')) {
          db.createObjectStore('favorites', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('recent')) {
          db.createObjectStore('recent', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('downloads')) {
          db.createObjectStore('downloads', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('uploads')) {
          db.createObjectStore('uploads', { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains('adminSketches')) {
          db.createObjectStore('adminSketches', { keyPath: 'id' });
        }
      };

      request.onsuccess = (e) => {
        this.db = e.target.result;
        resolve(this.db);
      };

      request.onerror = (e) => {
        console.warn('IndexedDB failed to open, falling back to LocalStorage', e);
        resolve(null);
      };
    });
  }

  // --- Auth State ---
  getUser() {
    const userStr = localStorage.getItem('sketchtrace_user');
    if (userStr) {
      try { return JSON.parse(userStr); } catch (e) {}
    }
