"/**
 * SketchTrace - Client-Side AI Sketch Converter Engine
 * Converts any user uploaded image into line art vector/canvas outlines:
 * - Pencil Sketch (Color Dodge algorithm)
 * - Outline Drawing (Sobel operator)
 * - Line Art (Adaptive Thresholding)
 * - Black & White High Contrast
 */

export class AIConverter {
  constructor() {
    this.canvas = document.createElement('canvas');
    this.ctx = this.canvas.getContext('2d');
  }

  // Converts Image object or DataURL based on mode & intensity parameters
  async convertImage(imageSource, mode = 'pencil', intensity = 50) {
    const img = await this.loadImage(imageSource);
    const width = img.width;
    const height = img.height;

    // Limit maximum dimensions for optimal mobile performance
    const maxDim = 1200;
    let targetW = width;
    let targetH = height;

    if (width > maxDim || height > maxDim) {
      if (width > height) {
        targetW = maxDim;
        targetH = Math.round((height * maxDim) / width);
      } else {
        targetH = maxDim;
        targetW = Math.round((width * maxDim) / height);
      }
    }

    this.canvas.width = targetW;
    this.canvas.height = targetH;
    this.ctx.drawImage(img, 0, 0, targetW, targetH);

    const imgData = this.ctx.getImageData(0, 0, targetW, targetH);
    const data = imgData.data;

    switch (mode) {
      case 'pencil':
        this.applyPencilSketchFilter(data, targetW, targetH, intensity);
        break;
      case 'outline':
        this.applySobelOutlineFilter(data, targetW, targetH, intensity);
        break;
      case 'lineart':
        this.applyAdaptiveLineArtFilter(data, targetW, targetH, intensity);
        break;
      case 'bw':
        this.applyHighContrastBWFilter(data, targetW, targetH, intensity);
        break;
      default:
        this.applyPencilSketchFilter(data, targetW, targetH, intensity);
    }

    this.ctx.putImageData(imgData, 0, 0);
    return this.canvas.toDataURL('image/png');
  }

