"/**
 * SketchTrace Screen Lock & Wake Lock Service
 * Keeps mobile display awake during sketch tracing and prevents accidental touch gestures.
 */

export class ScreenLockService {
  constructor() {
    this.wakeLock = null;
    this.isLocked = false;
    this.unlockTimer = null;
    this.unlockProgress = 0;
    this.onLockStateChange = null;
  }

  // Request Screen Wake Lock API to prevent screen timeout
  async requestWakeLock() {
    if ('wakeLock' in navigator) {
      try {
        this.wakeLock = await navigator.wakeLock.request('screen');
        this.wakeLock.addEventListener('release', () => {
          console.log('Screen Wake Lock was released');
        });
        return true;
      } catch (err) {
        console.warn('Wake Lock request error:', err);
        return false;
      }
    }
    return false;
  }

  // Release Wake Lock API
  async releaseWakeLock() {
    if (this.wakeLock) {
      try {
        await this.wakeLock.release();
        this.wakeLock = null;
      } catch (err) {
        console.warn('Wake Lock release error:', err);
      }
    }
  }

  // Enable Touch Lock
  lock(lockOverlayElement, callback) {
    this.isLocked = true;
    this.onLockStateChange = callback;
    this.requestWakeLock();

    if (lockOverlayElement) {
      lockOverlayElement.classList.remove('hidden');
      lockOverlayElement.classList.add('flex');
    }

    if (this.onLockStateChange) {
      this.onLockStateChange(true);
    }
  }

  // Disable Touch Lock
  unlock(lockOverlayElement) {
    this.isLocked = false;
    this.releaseWakeLock();

    if (lockOverlayElement) {
      lockOverlayElement.classList.add('hidden');
      lockOverlayElement.classList.remove('flex');
    }

    if (this.onLockStateChange) {
      this.onLockStateChange(false);
    }
